import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockDelta, bytes32 hash1, bytes32 hash2) public {
        // 1. Admissible domain: blockDelta > 0 so the guess can expire
        vm.assume(blockDelta > 0 && blockDelta < 256);
        address alice = address(0x1000);
        address bob = address(0x2000);

        // 2. Setup: fund both and have Alice lock in a guess
        vm.deal(alice, 2 ether);
        vm.deal(bob, 2 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(hash1);
        uint256 guessBlock = block.number + 1;

        // Advance past the guess block
        vm.roll(block.number + blockDelta);
        require(block.number > guessBlock, "did not advance past guess block");

        // Bob tries to front-run settlement by locking his own guess at same block? Not possible.
        // Instead, Bob advances further and settles his own guess to possibly alter blockhash availability.
        vm.roll(block.number + 1);

        // Bob locks a guess
        vm.prank(bob);
        c.lockInGuess{value: 1 ether}(hash2);
        uint256 bobGuessBlock = block.number + 1;

        vm.roll(block.number + blockDelta + 1);
        require(block.number > bobGuessBlock, "did not advance past bob's guess block");
        vm.prank(bob);
        c.settle(); // Bob settles his guess

        // Alice settles
        vm.prank(alice);
        bool aliceSettleSuccess = true;
        try c.settle() {
            aliceSettleSuccess = true;
        } catch {
            aliceSettleSuccess = false;
        }

        // The property: Alice's settlement attempt must succeed (not revert) regardless of Bob's actions.
        // The mutant allows overwriting guesses, potentially enabling Bob to interfere.
        assertTrue(aliceSettleSuccess);
    }
}

