pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint8 blockAdvance) public {
        // blockAdvance must be >= 1 so the settlement block is strictly after the lock block
        vm.assume(blockAdvance >= 1);
        vm.assume(blockAdvance <= 250); // keep it bounded but wide

        address user = address(0x1234); // fixed actor, fuzzing the hash and block offset
        vm.deal(user, 1 ether);

        // Lock in the guess
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guessHash);

        uint256 lockedBlock = c.guesses(user).block;

        // Advance the chain so that block.number > lockedBlock
        for (uint i = 0; i < blockAdvance; i++) {
            vm.roll(block.number + 1);
        }

        // Try to settle
        vm.prank(user);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: settlement must succeed because the locked block is in the past
        // Bug: lockedBlock == block.number at lock time, so if blockAdvance == 1,
        // settlement might fail because blockhash returns zero for the current block.
        // But the required invariant is that after lock, settle must work after a wait.
        // The actual property we test: if settle() reverts, then lockedBlock must be > lock-time block.number
        // (which can only happen in the bug: lockedBlock == lock block).
        // Simpler assertion: the stored block number after lockInGuess must be > block.number at call time.
        // Since we fuzz blockAdvance, we need to assert something about the contract's observable state.
        // We'll assert that the stored guess.block > the block when lockInGuess was called.
        // But we lost that variable because we advanced blocks. Let's re-approach:
        //
        // Property: For any lockInGuess(guessHash), the stored block number in guesses[msg.sender]
        // is strictly greater than the block.number at which lockInGuess executed.
        // The bug stores block.number, so the stored block equals the lock block, violating this.
        // We'll capture the block.number before lockInGuess and assert afterwards.
    }
}

