        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(sender).balance;

        // The reference invariant: if the submitted hash matches the blockhash of the locked block,
        // settle must succeed and transfer exactly 2 ether to the sender.
        // The mutant stores zero guess, so for any non-zero hash that matches the blockhash,
        // it will NOT pay out, breaking the invariant.
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(block.number - 1 - uint256(extraBlocks))));
        bool hashMatches = (hash == expectedAnswer);

        assertTrue(
            !hashMatches || (ok && balanceAfter == balanceBefore + 2 ether),
            "invariant broken: correct guess did not pay 2 ether"
        );
    }
}

