import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(address caller, bytes32 guessHash) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));

        uint256 stake = 1 ether;
        vm.deal(caller, stake);
        vm.prank(caller);
        c.lockInGuess{value: stake}(guessHash);

        vm.roll(block.number + 2);

        uint256 balBefore = caller.balance;
        vm.prank(caller);
        c.settle();
        uint256 balAfter = caller.balance;

        // If the guess was correct, the caller must receive exactly 1 ether net profit
        // (locked 1 ether + 1 ether profit = 2 ether returned, net +1 ether).
        // The bug gives only 1 ether total, so net profit is 0.
        // If the guess was incorrect, the caller receives nothing (net -1 ether),
        // but the invariant only constrains the correct case.
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 2)));
        if (guessHash == answer) {
            assertEq(balAfter - balBefore, 1 ether, "correct guess: net profit must be 1 ether");
        }
        // For incorrect guess, no assertion is needed; the invariant is vacuously true.
    }
}

